        k=len(ys)
        if k==0: return True
        pm=[0]*k; m=10**9
        for t in range(k):
            pm[t]=m; m=min(m,ys[t])
        sm=[0]*k; M=-1
        for t in range(k-1,-1,-1):
            sm[t]=M; M=max(M,ys[t])
        for t in range(k):
            if not (pm[t]<ys[t] or sm[t]>ys[t]): return False
        return True
    def Y_lo(lo,hi,v): return lo<v<hi
    dp=[0]*(n+2); dp[0]=1
    for j in range(1,n+1):
        s=0
        for i in range(0,j):
