import sys
def main():
    data=sys.stdin.read().split()
    N=int(data[0]); M=int(data[1])
    MOD=998244353
    INF=10**9
    minRL=[[INF]*N for _ in range(N)]
    idx=2
    for _ in range(M):
        L=int(data[idx])-1; R=int(data[idx+1])-1; X=int(data[idx+2])-1
        idx+=3
        if R<minRL[X][L]:
            minRL[X][L]=R
    G=[[INF]*(N+2) for _ in range(N)]
    for m in range(N):
        cur=INF
        for l in range(m,-1,-1):
            if minRL[m][l]<cur: cur=minRL[m][l]
            G[m][l]=cur
    C=[[0]*(N+1) for _ in range(N+1)]
    for i in range(N+1):
        C[i][0]=1
        for j in range(1,i+1):
            C[i][j]=(C[i-1][j-1]+C[i-1][j])%MOD
    # D[l][e]: interval [l,e) ; D[l][l]=1
    D=[[0]*(N+1) for _ in range(N+1)]
    for l in range(N+1):
        D[l][l]=1
    for ln in range(1,N+1):
        for l in range(0,N-ln+1):
            e=l+ln
            s=0
            Cr=C[ln-1]
            for m in range(l,e):
                if G[m][l]>=e-1+1 or G[m][l]>e-1:
                    # bad iff G[m][l] <= e-1
                    pass
                if G[m][l]>e-1:
                    s+=Cr[m-l]*D[l][m]%MOD*D[m+1][e]
            D[l][e]=s%MOD
    print(D[0][N]%MOD)
