from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        cp = conflictingPairs
        mx1=[0]*(n+2); mx2=[0]*(n+2)
        for x,y in cp:
            a,b=min(x,y),max(x,y)
            if a>mx1[b]:
                mx2[b]=mx1[b]; mx1[b]=a
            elif a>mx2[b]:
                mx2[b]=a
        a=mx1[:]
        P=[0]*(n+2)
        for r in range(1,n+1):
            P[r]=max(P[r-1],a[r])
        base=sum(r-P[r] for r in range(1,n+1))
        LOG=max(1,(n).bit_length())
        sp=[a[:]]
        for k in range(1,LOG+1):
            prev=sp[-1]; step=1<<(k-1)
            cur=[0]*(n+2)
            if (1<<k)<=n:
                for i in range(1,n+2-(1<<k)+1):
                    if i+(1<<k)-1<=n:
                        cur[i]=max(prev[i],prev[i+step])
            sp.append(cur)
        G=[0]*(n+2); nxt=[n+1]*(n+2)
        st=[]
        for i in range(n,0,-1):
            while st and a[st[-1]]<=a[i]:
                st.pop()
            nxt[i]=st[-1] if st else n+1
            st.append(i)
            G[i]=a[i]*(nxt[i]-i)+G[nxt[i]]
        def first_greater(b,c):
            pos=b+1
            for k in range(LOG,-1,-1):
                if pos+(1<<k)-1<=n and sp[k][pos]<=c:
                    pos+=1<<k
            return pos
        def S(b,c):
            t=first_greater(b,c)
            if t>n:
                t=n+1
            return c*(t-b)+G[t]
        res=-1
        for x,y in cp:
            aa,b=min(x,y),max(x,y)
            if aa==mx1[b]:
                c0=max(P[b-1],mx1[b]); c1=max(P[b-1],mx2[b])
                v=base+S(b,c0)-S(b,c1)
            else:
                v=base
            if v>res:
                res=v
        return res

