import sys
from math import factorial

def solve(A,B,M):
    N=A*B-1
    lam=[A]*(B-1)+[A-1]
    rows=len(lam)
    cur=[0]*rows
    T={}
    res=[0]
    def evac_e(T):
        cells=dict(T)
        E={}
        for k in range(N,0,-1):
            r,c=0,0
            while True:
                cand=[]
                if (r,c+1) in cells: cand.append((cells[(r,c+1)],(r,c+1)))
                if (r+1,c) in cells: cand.append((cells[(r+1,c)],(r+1,c)))
                if not cand: break
                v,p=min(cand)
                cells[(r,c)]=v
                r,c=p
            del cells[(r,c)]
            E[(r,c)]=k
        return max(E[p] for p in E if p[1]==0)
    def rec(v):
        if v>N:
            m1=max(T[(0,c)] for c in range(A))
            e=evac_e(T)
            if m1+e>=N+2: res[0]+=1
            return
        for r in range(rows):
            c=cur[r]
            if c<lam[r] and (r==0 or cur[r-1]>c):
                T[(r,c)]=v; cur[r]+=1
                rec(v+1)
                cur[r]-=1; del T[(r,c)]
    rec(1)
    lamc=[sum(1 for x in lam if x>j) for j in range(lam[0])]
    p=1
    for r in range(rows):
        for c in range(lam[r]):
            p*= (lam[r]-c-1)+(lamc[c]-r-1)+1
    f=factorial(N)//p
    return f*res[0]%M

