            if ch != '-':
                predmask[v][ch] = predmask[v].get(ch, 0) | (1 << u)
                succ[u].setdefault(ch, []).append(v)
    FULL = (1 << n) - 1
    unvis = [FULL] * n
    dist = [[-1] * n for _ in range(n)]
    MAXD = 2 * n * n + 10
    buckets = [[] for _ in range(MAXD)]
    for x in range(n):
        dist[x][x] = 0
        unvis[x] &= ~(1 << x)
        buckets[0].append((x, x))
    for u in range(n):
        for v in range(n):
            if C[u][v] != '-' and dist[u][v] == -1:
                dist[u][v] = 1
                unvis[v] &= ~(1 << u)
                buckets[1].append((u, v))
    for d in range(MAXD - 2):
        b = buckets[d]
        if not b:
            continue
        nd = d + 2
        for (u1, v1) in b:
            for c, lst in succ[v1].items():
                pm = predmask[u1].get(c, 0)
                if not pm:
                    continue
                for v in lst:
                    cand = pm & unvis[v]
                    if cand:
                        unvis[v] ^= cand
                        while cand:
                            low = cand & -cand
