import sys
from functools import lru_cache
sys.setrecursionlimit(10000)

def s(n):
    while n % 2 == 0:
        n //= 2
    return 1 if n % 4 == 1 else 0

def solve(A):
    @lru_cache(None)
    def G(items, cons):
        if not items:
            return 0
        if max(b for b, w in items) <= 1:
            best = 0
            for y in range(1, 64):
                if cons >= 0 and y % 2 != cons:
                    continue
                best = max(best, sum(w * (1 - s(y + b)) for b, w in items))
            return best
        best = -1
        for p in ([cons] if cons >= 0 else [0, 1]):
            Bp = {}
            for b, w in items:
                if (b + p) % 2 == 0:
                    k = (b + p) // 2
                    Bp[k] = Bp.get(k, 0) + w
            tb = tuple(sorted(Bp.items()))
            for q in (0, 1):
                f = sum(w for b, w in items if (b + p) % 2 == 1 and (2 * q + p + b) % 4 == 3)
                best = max(best, f + G(tb, q))
        return best
    return G(tuple(sorted((a, 1) for a in A)), -1)

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    A = [int(x) for x in data[1:1 + n]]
    print(solve(A))

main()

