class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid); m = len(grid[0])
        dirs = [(1,1),(1,-1),(-1,-1),(-1,1)]  # clockwise order
        def ok(a, b):
            return (a == 0 and b == 2) or (a == 2 and b == 0)
        f0 = []
        for di, dj in dirs:
            f = [[0]*m for _ in range(n)]
            ri = range(n-1, -1, -1) if di == 1 else range(n)
            rj = range(m-1, -1, -1) if dj == 1 else range(m)
            for i in ri:
                gi = grid[i]; fi = f[i]
                for j in rj:
                    v = gi[j]
                    if v == 0 or v == 2:
                        ni, nj = i+di, j+dj
                        if 0 <= ni < n and 0 <= nj < m and ok(v, grid[ni][nj]):
                            fi[j] = 1 + f[ni][nj]
                        else:
                            fi[j] = 1
            f0.append(f)
        f1 = []
        for k, (di, dj) in enumerate(dirs):
            f = [[0]*m for _ in range(n)]
            ci, cj = dirs[(k+1) % 4]
            ri = range(n-1, -1, -1) if di == 1 else range(n)
            rj = range(m-1, -1, -1) if dj == 1 else range(m)
            for i in ri:
                gi = grid[i]; fi = f[i]
                for j in rj:
                    v = gi[j]
                    if v == 0 or v == 2:
                        best = 1
                        ni, nj = i+di, j+dj
                        if 0 <= ni < n and 0 <= nj < m and ok(v, grid[ni][nj]):
                            best = max(best, 1 + f[ni][nj])
                        ti, tj = i+ci, j+cj
                        if 0 <= ti < n and 0 <= tj < m and ok(v, grid[ti][tj]):
                            best = max(best, 1 + f0[(k+1) % 4][ti][tj])
                        fi[j] = best
            f1.append(f)
        ans = 0
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1:
                    ans = max(ans, 1)
                    for k, (di, dj) in enumerate(dirs):
                        ni, nj = i+di, j+dj
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == 2:
                            ans = max(ans, 1 + f1[k][ni][nj])
        return ans

