from math import factorial
from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        used = [False] * (n + 1)

        def ways(q, r):
            if r == 0:
                return 1
            cq = sum(1 for v in range(1, n + 1) if not used[v] and v % 2 == q)
            co = sum(1 for v in range(1, n + 1) if not used[v] and v % 2 != q)
            if cq == (r + 1) // 2 and co == r // 2:
                return factorial(cq) * factorial(co)
            return 0

        res = []
        prev = None
        for pos in range(n):
            r = n - pos
            chosen = False
            for c in range(1, n + 1):
                if used[c]:
                    continue
                if prev is not None and c % 2 == prev:
                    continue
                used[c] = True
                w = ways(1 - c % 2, r - 1)
                if k <= w:
                    res.append(c)
                    prev = c % 2
                    chosen = True
                    break
                k -= w
                used[c] = False
            if not chosen:
                return []
        return res

