from typing import List
class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        ng = [n]*n
        st = []
        for j in range(n-1, -1, -1):
            while st and nums[st[-1]] <= nums[j]:
                st.pop()
            ng[j] = st[-1] if st else n
            st.append(j)
        W = [0]*(n+1)
        for j in range(n-1, -1, -1):
            W[j] = nums[j]*(ng[j]-j) + W[ng[j]]
        P = [0]*(n+1)
        for i in range(n):
            P[i+1] = P[i] + nums[i]
        sp = [list(range(n))]
        j = 1
        while (1 << j) <= n:
            prev = sp[-1]
            h = 1 << (j-1)
            cur = []
            for i in range(n - (1 << j) + 1):
                a = prev[i]; b = prev[i+h]
                cur.append(a if nums[a] >= nums[b] else b)
            sp.append(cur)
            j += 1
        lg = [0]*(n+2)
        for i in range(2, n+2):
            lg[i] = lg[i//2] + 1
        def cost(l, r):
            t = lg[r-l+1]
            a = sp[t][l]; b = sp[t][r-(1<<t)+1]
            q = a if nums[a] >= nums[b] else b
            sumM = W[l] - W[q] + nums[q]*(r-q+1)
            return sumM - (P[r+1]-P[l])
        total = 0
        for l in range(n):
            lo, hi = l, n-1
            while lo < hi:
                mid = (lo+hi+1)//2
                if cost(l, mid) <= k:
                    lo = mid
                else:
                    hi = mid-1
            total += lo - l + 1
        return total

