import random, heapq
from functools import lru_cache
def pref(a):
    n=len(a); res=[0]*(n+1)
    small=[]; large=[]; ss=0; sl=0
    for L in range(1,n+1):
        x=a[L-1]
        heapq.heappush(small,-x); ss+=x
        m=-heapq.heappop(small); ss-=m
        heapq.heappush(large,m); sl+=m
        if len(large)>len(small):
            y=heapq.heappop(large); sl-=y
            heapq.heappush(small,-y); ss+=y
        if L%2==0: res[L]=sl-ss
    return res
def fast(a):
    n=len(a); f=pref(a)
    if n%2==0: return f[n]
    g=pref(a[::-1])
    return max(f[L]+g[n-1-L] for L in range(0,n,2))
def brute(a):
    @lru_cache(None)
    def go(t):
        if len(t)<=1: return 0
        b=-1
        for i in range(len(t)-1):
            v=abs(t[i]-t[i+1])+go(t[:i]+t[i+2:])
            b=max(b,v)
        return b
    return go(tuple(a))
