class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        A, B, C = p.split('*')
        n = len(s)

        def occ(x):
            m = len(x)
            if m == 0:
                return list(range(n + 1))
            pi = [0] * m
            k = 0
            for i in range(1, m):
                while k and x[i] != x[k]:
                    k = pi[k - 1]
                if x[i] == x[k]:
                    k += 1
                pi[i] = k
            res = []
            k = 0
            for i, ch in enumerate(s):
                while k and ch != x[k]:
                    k = pi[k - 1]
                if ch == x[k]:
                    k += 1
                if k == m:
                    res.append(i - m + 1)
                    k = pi[k - 1]
            return res

        oa, ob, oc = occ(A), occ(B), occ(C)
        best = -1
        for a in oa:
            k = bisect.bisect_left(ob, a + len(A))
            if k == len(ob):
                continue
            b = ob[k]
            k2 = bisect.bisect_left(oc, b + len(B))
            if k2 == len(oc):
                continue
            c = oc[k2]
            length = c + len(C) - a
            if best == -1 or length < best:
                best = length
        return best

