def brute(N,M):
    V=N*M+1
    adj={v:[] for v in range(V)}
    for i in range(1,V):
        p=max(i-N,0); adj[i].append(p); adj[p].append(i)
    full=(1<<V)-1
    start=(0,1); seen={start}; stack=[start]
    while stack:
        pos,mask=stack.pop()
