    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        P = [0] * (n + 1)
        for i, x in enumerate(nums):
            P[i + 1] = P[i] + x
        INF = float('inf')
        minv = [INF] * k
        ans = -INF
        for i in range(k, n + 1):
            r = (i - k) % k
            if P[i - k] < minv[r]:
                minv[r] = P[i - k]
            v = P[i] - minv[i % k]
            if v > ans:
                ans = v
        return int(ans)

