class Solution:
    def countPairs(self, nums: List[int]) -> int:
        def reach(x):
            s = str(x)
            res = {x}
            L = len(s)
            for i in range(L):
                for j in range(i + 1, L):
                    t = list(s)
                    t[i], t[j] = t[j], t[i]
                    res.add(int("".join(t)))
            return res
        R = [reach(x) for x in nums]
        n = len(nums)
        cnt = 0
        for i in range(n):
            for j in range(i + 1, n):
                if nums[j] in R[i] or nums[i] in R[j]:
                    cnt += 1
        return cnt

