import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        N = 10000
        sieve = [True] * N
        sieve[0] = sieve[1] = False
        for i in range(2, 100):
            if sieve[i]:
                for j in range(i * i, N, i):
                    sieve[j] = False
        if sieve[n] or sieve[m]:
            return -1
        L = len(str(n))
        if n == m:
            return n
        INF = float('inf')
        dist = {n: n}
        pq = [(n, n)]
        while pq:
            d, u = heapq.heappop(pq)
            if d > dist.get(u, INF):
                continue
            if u == m:
                return d
            for i in range(L):
                pw = 10 ** (L - 1 - i)
                dig = (u // pw) % 10
                base = u - dig * pw
                for nd in (dig - 1, dig + 1):
                    if 0 <= nd <= 9:
                        v = base + nd * pw
                        if sieve[v]:
                            continue
                        nc = d + v
                        if nc < dist.get(v, INF):
                            dist[v] = nc
                            heapq.heappush(pq, (nc, v))
        return -1

